        ],
        "architecture_influence": "Validates token-based unification approach"
      },
      {
        "id": "paper_001", 
        "title": "Visual Instruction Tuning (LLaVA)",
        "relevance": "Reference for visual instruction tuning methodology",
        "key_contributions": [
          "GPT-4 generated multimodal instruction-following data",
          "CLIP ViT + LLM connection via linear projection",
          "End-to-end training for general-purpose visual assistant"
        ],
        "architecture_influence": "Inspires understanding encoder design (CLIP ViT + projection)"
      },
      {
        "id": "paper_002",
        "title": "Sigmoid Loss for Language Image Pre-Training (SigLIP)",
        "relevance": "Efficient contrastive pre-training method",
        "key_contributions": [
          "Pairwise sigmoid loss instead of softmax contrastive",
          "Decouples batch size from loss computation",
          "Enables training with fewer resources"
        ],
        "architecture_influence": "Supports CLIP encoder choice for understanding pathway"
      },
      {
        "id": "paper_003",
        "title": "Autoregressive Model Beats Diffusion: Llama for Scalable Image Generation (LlamaGen)",
        "relevance": "Primary reference for autoregressive image generation",
        "key_contributions": [
          "Vanilla autoregressive models achieve SOTA image generation",
          "VQ-VAE tokenizer with 16x downsampling, 0.94 rFID",
          "Llama architecture without vision-specific inductive biases",
          "2.18 FID on ImageNet 256x256 with 3.1B model"
        ],
        "architecture_influence": "Validates VQ-VAE + Llama for generation pathway"
      }
    ]
  },
  "method_validation": {
    "decoupled_encoding_rationale": "Supported by LlamaGen (generation needs discrete tokens) and LLaVA (understanding benefits from CLIP features)",
    "unified_backbone_rationale": "Supported by Chameleon (early fusion works) and LlamaGen (vanilla Llama architecture sufficient)",
